async fn model_call(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    Json(input): Json<ModelCallHttpRequest>,
) -> Response {
    let role = input.role;
    let authenticated = match role {
        factory_native::db::ModelCallRole::SemanticReviewer => {
            quality_role(&app, &headers) == Some(QualityRole::Reviewer)
        }
        factory_native::db::ModelCallRole::Evaluation => authorized(&headers, &app.operator_token),
        factory_native::db::ModelCallRole::Lead => false,
    };
    if !authenticated {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    if role == factory_native::db::ModelCallRole::SemanticReviewer {
        let settings = match app.db.factory_settings().await {
            Ok(settings) => settings,
            Err(error) => return api_error(error),
        };
        if !settings.semantic_review_enabled {
            return (
                StatusCode::FORBIDDEN,
                Json(json!({"error":"semantic review is disabled by the operator"})),
            )
                .into_response();
        }
    }
    if matches!(
        role,
        factory_native::db::ModelCallRole::SemanticReviewer
            | factory_native::db::ModelCallRole::Evaluation
    ) && input.scope_id != input.objective_id
    {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error":"model call scope must identify the objective"})),
        )
            .into_response();
    }
    let gateway = match role {
        factory_native::db::ModelCallRole::SemanticReviewer => {
            app.semantic_reviewer_gateway(&input.objective_id).await
        }
        factory_native::db::ModelCallRole::Evaluation => app
            .current_model_gateway()
            .await
            .ok_or_else(|| factory_native::model_routing::RouteError::Invalid {
                provider: String::new(),
                model: String::new(),
                detail: "the deployment default model gateway is not configured".into(),
            }),
        factory_native::db::ModelCallRole::Lead => {
            return StatusCode::UNAUTHORIZED.into_response();
        }
    };
    let gateway = match gateway {
        Ok(gateway) => gateway,
        Err(route_error) => {
            return (
                StatusCode::SERVICE_UNAVAILABLE,
                Json(json!({
                    "error": route_error.to_string(),
                    "code": "MODEL_ROUTE_UNAVAILABLE",
                    "routeCode": route_error.code(),
                })),
            )
                .into_response();
        }
    };
    match gateway
        .call(
            &app.db,
            factory_native::model_gateway::ModelCallRequest {
                role,
                principal_id: &input.principal_id,
                project_id: &input.project_id,
                objective_id: &input.objective_id,
                scope_id: &input.scope_id,
                purpose: &input.purpose,
                system_prompt: &input.system_prompt,
                user_prompt: &input.user_prompt,
                max_output_tokens: input.max_output_tokens,
            },
        )
        .await
    {
        Ok(result) => Json(json!({
            "reservationId": result.reservation_id,
            "provider": result.provider,
            "model": result.model,
            "requestSha256": result.request_sha256,
            "content": result.content,
            "inputTokens": result.input_tokens,
            "outputTokens": result.output_tokens,
            "totalTokens": result.total_tokens,
            "costMicros": result.cost_micros,
            "usageKnown": result.usage_known
        }))
        .into_response(),
        Err(factory_native::model_gateway::ModelGatewayError::Invalid(message)) => {
            (StatusCode::BAD_REQUEST, Json(json!({"error": message}))).into_response()
        }
        Err(factory_native::model_gateway::ModelGatewayError::Database(error)) => api_error(error),
        Err(error) => (
            StatusCode::BAD_GATEWAY,
            Json(json!({"error": error.to_string()})),
        )
            .into_response(),
    }
}

async fn quality_receipt(State(app): State<Arc<App>>, headers: HeaderMap, body: Bytes) -> Response {
    let Some(identity) = quality_identity(&app, &headers) else {
        return StatusCode::UNAUTHORIZED.into_response();
    };
    let input: QualityReceiptRequest = match serde_json::from_slice(&body) {
        Ok(input) => input,
        Err(_) => {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({"error":"invalid receipt payload"})),
            )
                .into_response();
        }
    };
    if input.principal_id != identity.principal_id {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "error": "receipt principal does not match the authenticated quality identity",
                "code": "QUALITY_PRINCIPAL_MISMATCH",
            })),
        )
            .into_response();
    }
    if input.reviewer_role != identity.reviewer_role {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "error": "receipt reviewer role does not match the authenticated quality identity",
                "code": "QUALITY_ROLE_MISMATCH",
            })),
        )
            .into_response();
    }
    let role = identity.role;
    if role == QualityRole::Reviewer {
        let required = match app.db.candidate_reviewer_roles(&input.candidate_id).await {
            Ok(required) => required,
            Err(error) => return api_error(error),
        };
        if !required.is_empty()
            && !input
                .reviewer_role
                .is_some_and(|reviewer_role| required.contains(&reviewer_role))
        {
            return (
                StatusCode::FORBIDDEN,
                Json(json!({
                    "error": "receipt reviewer role is not required by the frozen reviewer plan",
                    "code": "QUALITY_ROLE_MISMATCH",
                })),
            )
                .into_response();
        }
    }
    let receipt = QualityReceiptInput {
        receipt_id: input.receipt_id,
        principal_id: input.principal_id,
        reviewer_role: input.reviewer_role,
        action_spec_sha256: input.action_spec_sha256,
        commit_sha: input.commit_sha,
        tree_sha: input.tree_sha,
        result: input.result,
        evidence: input.evidence,
        findings: input.findings,
        mechanism: input.mechanism,
        model_provider: input.model_provider,
        model_name: input.model_name,
        model_reservation_id: input.model_reservation_id,
        model_request_sha256: input.model_request_sha256,
        input_tokens: input.input_tokens,
        output_tokens: input.output_tokens,
        total_tokens: input.total_tokens,
        cost_micros: input.cost_micros,
        usage_known: input.usage_known,
    };
    match app
        .db
        .record_quality_receipt(&input.candidate_id, role, &receipt)
        .await
    {
        Ok(result) => (StatusCode::CREATED, Json(result)).into_response(),
        Err(error) => api_error(error),
    }
}

async fn create_delegation(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    Json(input): Json<NewDelegation>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let mut delegation = input.delegation;
    if delegation.content_hash.is_empty() {
        delegation.content_hash = delegation.compute_content_hash();
    }
    if delegation.autonomous_start && !app.lead_autonomous_start {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({"error":"autonomous delegation policy is not ratified or activated"})),
        )
            .into_response();
    }
    match app
        .db
        .create_standing_delegation(&delegation, &input.idempotency_key)
        .await
    {
        Ok((delegation, created)) => (
            if created {
                StatusCode::CREATED
            } else {
                StatusCode::OK
            },
            Json(delegation),
        )
            .into_response(),
        Err(error) => api_error(error),
    }
}

async fn get_delegation(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let usage = match app.db.delegation_usage(&id).await {
        Ok(usage) => usage,
        Err(error) => return api_error(error),
    };
    match app.db.standing_delegation_v2(&id).await {
        Ok(delegation) => Json(json!({
            "delegation": delegation,
            "usage": usage,
            "schemaVersion": 2,
        }))
        .into_response(),
        Err(Error::NotFound) | Err(Error::Forbidden(_)) => {
            match app.db.standing_delegation(&id).await {
                Ok(delegation) => Json(json!({
                    "delegation": delegation,
                    "usage": usage,
                    "schemaVersion": 1,
                    "historical": true,
                }))
                .into_response(),
                Err(error) => api_error(error),
            }
        }
        Err(error) => api_error(error),
    }
}

