async fn create_lead_request(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    session: Option<Extension<factory_native::db::DeviceSessionRecord>>,
    Json(input): Json<NewLeadRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let (principal_id, _) =
        authenticated_operator(session.as_ref().map(|Extension(device)| device));
    match app
        .db
        .create_lead_request(
            &input.project_id,
            &input.action_id,
            &input.delegation_id,
            &input.objective,
            &input.project_config_hash,
            &input.idempotency_key,
        )
        .await
    {
        Ok((request, created)) => {
            if let Some(authorized_micros) = input.authorized_micros {
                let action = match app.db.action(&request.action_id).await {
                    Ok(action) => action,
                    Err(error) => return api_error(error),
                };
                let grant = match app.db.standing_delegation_v2(&request.delegation_id).await {
                    Ok(grant) => grant,
                    Err(error) => return api_error(error),
                };
                if let Err(error) = ensure_inference_pricing_quote(
                    &app,
                    &grant.route.provider,
                    &grant.route.model,
                    &principal_id,
                )
                .await
                {
                    return api_error(error);
                }
                if let Err(error) = ensure_request_inference_envelope(
                    &app,
                    &request.id,
                    &request.project_id,
                    Some(authorized_micros),
                    &principal_id,
                    &request_scope_digest(&[
                        "lead-request-scope",
                        &request.project_id,
                        &request.action_id,
                        &grant.id,
                        &action.spec_sha256,
                    ]),
                    &request.request_hash,
                )
                .await
                {
                    return api_error(error);
                }
            }
            (
                if created {
                    StatusCode::CREATED
                } else {
                    StatusCode::OK
                },
                Json(request),
            )
                .into_response()
        }
        Err(error) => api_error(error),
    }
}

async fn assess_lead_request(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let request = match app.db.lead_request(&id).await {
        Ok(request) => request,
        Err(error) => return api_error(error),
    };
    match app.db.lead_withdrawal(&id).await {
        Ok(Some(_)) => return api_error(Error::Withdrawn),
        Ok(None) => {}
        Err(error) => return api_error(error),
    }
    let config = match app.db.project_config(&request.project_id).await {
        Ok(config) => config,
        Err(error) => return api_error(error),
    };
    let action = match app.db.action(&request.action_id).await {
        Ok(action) => action,
        Err(error) => return api_error(error),
    };
    let grant = match app.db.standing_delegation_v2(&request.delegation_id).await {
        Ok(grant) => grant,
        Err(error) => return api_error(error),
    };
    let current_gateway = app.current_model_gateway().await;
    if current_gateway.is_none() && !app.lead_fixture_assessor {
        return (
            StatusCode::NOT_IMPLEMENTED,
            Json(json!({"error":"no model gateway is authorized; configure FACTORY_MODEL_URL or set FACTORY_LEAD_FIXTURE_ASSESSOR=1 only for deterministic tests"})),
        )
            .into_response();
    }
    if let Some(gateway) = &current_gateway {
        // The assessment is billable. It must be charged to the one request
        // envelope created from the operator's explicit amount; never dispatch
        // a paid call without one.
        match app.db.inference_envelope_for_request(&id).await {
            Ok(Some(_)) => {}
            Ok(None) => {
                return api_error(Error::IntakeConflict {
                    code: "INFERENCE_AUTHORIZATION_REQUIRED",
                    message:
                        "billable Lead assessment requires an explicit operator-authorized monetary amount at request creation"
                            .into(),
                });
            }
            Err(error) => return api_error(error),
        }
        if let Err(error) = ensure_inference_pricing_quote(
            &app,
            gateway.provider(),
            gateway.model(),
            "lead-assessment",
        )
        .await
        {
            return api_error(error);
        }
    }
    if request.state == factory_native::lead::LeadRequestState::Submitted
        && let Err(error) = app.db.begin_lead_assessment(&id).await
    {
        return api_error(error);
    }
    let action_binding = factory_native::lead::ActionBinding {
        id: action.id.clone(),
        project_id: action.project_id.clone(),
        status: factory_native::lead::ActionStatus::Pending,
    };
    let mechanism = if current_gateway.is_some() {
        "MODEL"
    } else {
        "FIXTURE"
    };
    let greenfield = agentic_stack_for_project(&app, &request.project_id)
        .await
        .languages
        .is_empty();
    let (mut assessment, proposal) = if let Some(gateway) = &current_gateway {
        match factory_native::lead_model::assess(
            gateway,
            &app.db,
            factory_native::lead_model::AssessmentRequest {
                request_id: &request.id,
                project: &config,
                action: &action_binding,
                action_spec: &action.spec,
                objective: &request.objective,
                grant: &grant,
                now: chrono::Utc::now(),
                greenfield,
            },
        )
        .await
        {
            Ok(value) => value,
            Err(error) => {
                if matches!(
                    error,
                    factory_native::lead::LeadError::TransientAssessment(_)
                ) {
                    return (
                        StatusCode::SERVICE_UNAVAILABLE,
                        Json(json!({"error": error.to_string()})),
                    )
                        .into_response();
                }
                let _ = app.db.block_lead_request(&id, &error.to_string()).await;
                return api_error(error.into());
            }
        }
    } else {
        match factory_native::lead::fixture_lead_assessment(
            &request.id,
            &config,
            &action_binding,
            &action.spec,
            &request.objective,
            &grant,
            chrono::Utc::now(),
        ) {
            Ok((assessment, proposal)) => (assessment, Some(proposal)),
            Err(error) => {
                let _ = app.db.block_lead_request(&id, &error.to_string()).await;
                return api_error(error.into());
            }
        }
    };
    let input = factory_native::lead::AssessmentInput {
        project_id: request.project_id.clone(),
        action_id: request.action_id.clone(),
        request_id: request.id.clone(),
        objective: request.objective.clone(),
        allowed_evidence_refs: std::collections::BTreeSet::from(["repository-files".to_string()]),
    };
    let assessment_record = match app
        .db
        .record_lead_assessment(
            &id,
            mechanism,
            &assessment,
            &input,
            &format!("{mechanism}-assessment:{id}"),
        )
        .await
    {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let Some(mut proposal) = proposal else {
        let _ = app
            .db
            .block_lead_request(
                &id,
                "informational_assessment: no execution plan is required for this intent",
            )
            .await;
        return (
            StatusCode::OK,
            Json(json!({
                "assessment": assessment_record,
                "proposal": null,
                "informational": true
            })),
        )
            .into_response();
    };
    let requested_units = if app.lead_fixture_assessor {
        env::var("FACTORY_LEAD_FIXTURE_UNITS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or(1)
            .clamp(1, 8)
    } else {
        1
    };
    if requested_units > 1 {
        let fanin = env::var("FACTORY_LEAD_FIXTURE_MODE").ok().as_deref() == Some("fanin");
        proposal.budget.max_attempts = 1;
        proposal.max_sessions = (1 + requested_units) as u32;
        proposal.work_units = (1..=requested_units)
            .map(|index| factory_native::lead::LeadWorkUnit {
                id: format!("unit-{index}"),
                kind: factory_native::lead::WorkUnitKind::Implementation,
                description: format!("Unit {index}"),
                depends_on: if fanin && index > 2 {
                    vec!["unit-1".into(), "unit-2".into()]
                } else {
                    Vec::new()
                },
                allowed_paths: vec![format!("src/unit-{index}.txt")],
                capabilities: config.capabilities.clone(),
                acceptance_criteria: Vec::new(),
                negative_cases: Vec::new(),
            })
            .collect();
        assessment.proposal = Some(proposal.clone());
    }
    let proposal_record = match app
        .db
        .record_lead_proposal(&id, &proposal, &format!("{mechanism}-proposal:{id}"))
        .await
    {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    (
        StatusCode::OK,
        Json(json!({
            "assessment": assessment_record,
            "proposal": proposal_record
        })),
    )
        .into_response()
}

