/// Exact owner-decision matter and selected option that authorize a finding
/// refutation. A generic APPROVED decision for another purpose must never close
/// a reviewer finding.
const FINDING_REFUTATION_MATTER: &str = "FINDING_REFUTATION";
const FINDING_REFUTATION_APPROVE_OPTION: &str = "APPROVE_REFUTATION";

fn owner_decision_allows_refutation(
    decision: &factory_native::db::AgenticOwnerDecisionRecord,
    principal: &str,
    request_id: &str,
    project_id: &str,
) -> bool {
    let scoped = decision.request_id.as_deref() == Some(request_id)
        || (decision.request_id.is_none() && decision.project_id == project_id);
    decision.status == "APPROVED"
        && decision.resolved_by.as_deref() == Some(principal)
        && decision.matter == FINDING_REFUTATION_MATTER
        && decision.selected_option.as_deref() == Some(FINDING_REFUTATION_APPROVE_OPTION)
        && decision
            .options
            .iter()
            .any(|option| option == FINDING_REFUTATION_APPROVE_OPTION)
        && scoped
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct AgenticFindingDispositionInput {
    status: String,
    #[serde(default)]
    evidence_refs: Vec<String>,
    #[serde(default)]
    owner_decision: Option<String>,
}

async fn resolve_agentic_finding(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    session: Option<Extension<factory_native::db::DeviceSessionRecord>>,
    AxumPath((id, finding_id)): AxumPath<(String, String)>,
    Json(input): Json<AgenticFindingDispositionInput>,
) -> Response {
    use factory_native::planning::{FindingDisposition, FindingStatus};
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let existing = match app.db.finding_disposition(&record.id, &finding_id).await {
        Ok(existing) => existing,
        Err(error) => return api_error(error),
    };
    let route = match factory_native::planning::findings::parse_route_code(&existing.route) {
        Some(route) => route,
        None => {
            return api_error(Error::Invalid("stored finding route is invalid"));
        }
    };
    let status = match input.status.as_str() {
        "RESOLVED" => FindingStatus::Resolved,
        "REFUTED" => FindingStatus::Refuted,
        _ => {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "status must be RESOLVED or REFUTED", "code": "FINDING_STATUS_INVALID"})),
            )
                .into_response();
        }
    };
    let principal = operator_principal(session.as_ref().map(|Extension(device)| device));
    if status == FindingStatus::Refuted {
        let decision_id = match input.owner_decision.as_deref() {
            Some(value) if !value.trim().is_empty() => value,
            _ => {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({"error": "a refutation requires an owner decision reference", "code": "OWNER_DECISION_REQUIRED"})),
                )
                    .into_response();
            }
        };
        let decision = match app.db.agentic_owner_decision(decision_id).await {
            Ok(decision) => decision,
            Err(Error::NotFound) => {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({"error": "the owner decision reference does not exist", "code": "OWNER_DECISION_INVALID"})),
                )
                    .into_response();
            }
            Err(error) => return api_error(error),
        };
        // A refutation is permitted only by the authenticated owner's approved
        // decision. The owner-decision schema records APPROVED/DENIED; it never
        // records a separate RESOLVED status, so acceptance must bind APPROVED.
        if !owner_decision_allows_refutation(&decision, &principal, &record.id, &record.project_id)
        {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "the owner decision is not an approved decision by this owner for this request", "code": "OWNER_DECISION_INVALID"})),
            )
                .into_response();
        }
    }
    let disposition = FindingDisposition {
        request_id: record.id.clone(),
        finding_id,
        route,
        status,
        candidate_id: existing.candidate_id.clone().unwrap_or_default(),
        reviewer_principal: existing.reviewer_principal.clone(),
        resolved_by: if status == FindingStatus::Resolved {
            principal.clone()
        } else {
            existing.resolved_by.clone()
        },
        evidence_refs: input.evidence_refs,
        owner_principal: (status == FindingStatus::Refuted).then_some(principal),
        owner_decision: input.owner_decision,
    };
    if let Err(error) = disposition.validate() {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error": error, "code": "FINDING_DISPOSITION_INVALID"})),
        )
            .into_response();
    }
    match app.db.save_finding_disposition(&disposition).await {
        Ok(saved) => {
            if let Some(candidate_id) = saved
                .candidate_id
                .as_deref()
                .filter(|candidate_id| !candidate_id.is_empty())
            {
                match app.db.gate_for_candidate(candidate_id).await {
                    Ok(Some(_)) => {
                        if let Err(error) = app.db.reevaluate_gate_for_candidate(candidate_id).await
                        {
                            return api_error(error);
                        }
                    }
                    Ok(None) => {}
                    Err(error) => return api_error(error),
                }
            }
            Json(saved).into_response()
        }
        Err(error) => api_error(error),
    }
}

struct ParticipantPlanFailure {
    code: &'static str,
    message: String,
}

async fn deterministic_participant_plan(
    app: &App,
    record: &factory_native::db::IntakeRequestRecord,
    context: &AgenticTriageContext,
    graph: &factory_native::agentic::ValidatedWorkGraph,
) -> Result<factory_native::agentic::ParticipantPlan, ParticipantPlanFailure> {
    let profile = app
        .db
        .execution_profile_revision(&record.profile_id, &record.profile_revision_id)
        .await
        .map_err(|_| ParticipantPlanFailure {
            code: "PROFILE_NOT_EXECUTABLE",
            message: "the frozen execution profile is not executable".into(),
        })?;
    let content = profile.content.v2().ok_or(ParticipantPlanFailure {
        code: "PROFILE_NOT_EXECUTABLE",
        message: "the frozen execution profile has no executable v2 content".into(),
    })?;
    let reviewer_plan = factory_native::planning::route::required_reviewers(
        context.planning_lane,
        context.assurance(),
    );
    let reviewer_assignments = app
        .reviewer_identities
        .assignments_for_plan(
            &reviewer_plan,
            &content.roles.semantic_reviewer.provider,
            &content.roles.semantic_reviewer.model,
        )
        .map_err(|message| ParticipantPlanFailure {
            code: "REVIEWER_INDEPENDENCE_REQUIRED",
            message,
        })?;
    let mut plan = factory_native::agentic::participant_plan_for_graph(
        context.triage.route,
        context.assurance(),
        graph,
        &context.stack,
        &content.roles.implementer.provider,
        &content.roles.implementer.model,
        "",
    );
    plan.reviewer_count = u32::try_from(reviewer_assignments.len()).unwrap_or(u32::MAX);
    plan.reviewer_roles = reviewer_plan.required.clone();
    plan.reviewer_assignments = reviewer_assignments;
    for assignment in &mut plan.assignments {
        if assignment.role == "Reviewer" {
            assignment.count = plan.reviewer_count;
        }
    }
    plan.reasons.push(format!(
        "{} required reviewer roles are staffed by {} distinct authenticated reviewer identities; provider and model equality is not a rejection criterion.",
        plan.reviewer_roles.len(),
        plan.reviewer_count
    ));
    Ok(plan)
}

async fn get_agentic_participants(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    match app.db.agentic_participant_plan(&record.id).await {
        Ok(record) => Json(json!({"plan": record})).into_response(),
        Err(Error::NotFound) => Json(json!({"plan": null})).into_response(),
        Err(error) => api_error(error),
    }
}

async fn record_agentic_participants(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let graph_record = match app.db.agentic_work_graph(&record.id).await {
        Ok(graph) => graph,
        Err(Error::NotFound) => {
            return agentic_conflict(
                "WORK_GRAPH_REQUIRED",
                "a validated Planner WorkGraph is required before participant compilation",
            );
        }
        Err(error) => return api_error(error),
    };
    let graph = match parse_graph_record(&graph_record) {
        Ok(graph) => graph,
        Err(response) => return *response,
    };
    let context = match agentic_triage_context(&app, &record).await {
        Ok(context) => context,
        Err(error) => return api_error(error),
    };
    let plan = match deterministic_participant_plan(&app, &record, &context, &graph).await {
        Ok(plan) => plan,
        Err(failure) => return agentic_conflict(failure.code, &failure.message),
    };
    match app
        .db
        .save_agentic_participant_plan(&record.id, Some(&graph.graph_sha256), &plan)
        .await
    {
        Ok(record) => {
            if let Err(error) = try_freeze_approved_plan(&app, &record.request_id, &context).await {
                return api_error(error);
            }
            let workflow = app
                .db
                .workflow_run_for_request(&record.request_id)
                .await
                .ok()
                .flatten();
            Json(json!({"plan": record, "compiled": plan, "workflow": workflow})).into_response()
        }
        Err(error) => api_error(error),
    }
}

async fn get_agentic_spec(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let frozen = match app.db.agentic_spec(&record.id).await {
        Ok(spec) if spec.state == "FROZEN" => Some(spec),
        Ok(_) => None,
        Err(Error::NotFound) => None,
        Err(error) => return api_error(error),
    };
    let draft = match app.db.agentic_spec_draft(&record.id).await {
        Ok(draft) => Some(draft),
        Err(Error::NotFound) => None,
        Err(error) => return api_error(error),
    };
    let graph = match app.db.agentic_work_graph(&record.id).await {
        Ok(graph) => Some(graph),
        Err(Error::NotFound) => None,
        Err(error) => return api_error(error),
    };
    let publication = match app
        .db
        .agentic_spec_publication(
            frozen
                .as_ref()
                .map(|spec| spec.id.as_str())
                .unwrap_or_default(),
        )
        .await
    {
        Ok(publication) => Some(publication),
        Err(Error::NotFound) => None,
        Err(error) => return api_error(error),
    };
    let issues = match &frozen {
        Some(spec) => match app.db.agentic_spec_issues(&spec.id).await {
            Ok(issues) => issues,
            Err(error) => return api_error(error),
        },
        None => Vec::new(),
    };
    let github_bound = app
        .db
        .project_github_binding(&record.project_id)
        .await
        .is_ok();
    Json(json!({
        "frozen": frozen.map(|spec| {
            let parsed = spec
                .frozen_json
                .as_deref()
                .and_then(|json| serde_json::from_str::<factory_native::agentic::FrozenSpec>(json).ok());
            json!({"record": spec, "spec": parsed})
        }),
        "draft": draft.map(|spec| {
            let preview = serde_json::from_str::<factory_native::agentic::SpecDraftModel>(&spec.draft_json)
                .ok()
                .and_then(|draft| factory_native::agentic::compile_spec(&draft, spec.revision).ok());
            json!({"record": spec, "preview": preview})
        }),
        "graph": graph,
        "publication": publication,
        "issues": issues,
        "githubBound": github_bound,
    }))
    .into_response()
}

fn validate_spec_unit_mapping(
    frozen: &factory_native::agentic::FrozenSpec,
    graph: &factory_native::agentic::ValidatedWorkGraph,
) -> Result<(), String> {
    let unit_ids = graph
        .units
        .iter()
        .map(|unit| unit.id.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    for requirement in &frozen.requirements {
        if requirement.work_unit_id.is_empty()
            || !unit_ids.contains(requirement.work_unit_id.as_str())
        {
            return Err(format!(
                "requirement {} must bind an exact WorkGraph unit id",
                requirement.id
            ));
        }
    }
    for unit in &graph.units {
        if !frozen
            .requirements
            .iter()
            .any(|requirement| requirement.work_unit_id == unit.id)
        {
            return Err(format!(
                "WorkGraph unit {} is not covered by any requirement",
                unit.id
            ));
        }
    }
    Ok(())
}

async fn author_agentic_spec(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let context = match agentic_triage_context(&app, &record).await {
        Ok(context) => context,
        Err(error) => return api_error(error),
    };
    if !matches!(
        context.triage.route,
        factory_native::agentic::ChangeRoute::FormalSpec
    ) {
        return agentic_conflict(
            "SPEC_NOT_REQUIRED",
            "the Spec Manager authors only FORMAL_SPEC requests",
        );
    }
    let graph_record = match app.db.agentic_work_graph(&record.id).await {
        Ok(graph) => graph,
        Err(Error::NotFound) => {
            return agentic_conflict(
                "WORK_GRAPH_REQUIRED",
                "a validated Planner WorkGraph is required before specification",
            );
        }
        Err(error) => return api_error(error),
    };
    let graph = match parse_graph_record(&graph_record) {
        Ok(graph) => graph,
        Err(response) => return *response,
    };
    let current = match app.db.agentic_spec(&record.id).await {
        Ok(spec) => Some(spec),
        Err(Error::NotFound) => None,
        Err(error) => return api_error(error),
    };
    let (revision, has_frozen) = match &current {
        Some(spec) if spec.state == "FROZEN" => (spec.revision + 1, true),
        Some(spec) => (spec.revision, false),
        None => (1, false),
    };
    let config = app.db.project_config(&record.project_id).await.ok();
    let schema = factory_native::model_output::spec_draft_schema();
    let schema_sha256 = factory_native::model_output::spec_draft_schema_sha256();
    let system_prompt = format!(
        "You are the bounded Software Factory Spec Manager. Return ONLY one JSON object that validates against the JSON Schema below. Do not add prose, markdown, comments or unknown fields. You are read-only: you cannot use tools, write files, grant authority, approve work or change a frozen specification. Author observable formal requirements for a FORMAL_SPEC request. Every requirement must state an observable behavior and carry at least one acceptance case and at least one negative case. Acceptance and negative cases must be concrete and testable, not implementation instructions. Do not invent scope outside the objective and WorkGraph. Every requirement MUST set workUnitId to the exact id of the WorkGraph unit that implements it; cover every WorkGraph unit with at least one requirement and never invent a unit id. Requirements are numbered deterministically by Core after you return; assertion and check identities are also compiled by Core.

JSON Schema:
{schema}"
    );
    let user_prompt = serde_json::json!({
        "objective": record.objective,
        "route": context.triage.route,
        "assurance": context.assurance(),
        "risk": format!("{:?}", context.risk),
        "revision": revision,
        "supersedesFrozenRevision": has_frozen,
        "workGraph": {
            "units": graph.units,
            "topologicalOrder": graph.topological_order,
        },
        "stack": context.stack,
        "projectConfig": config.as_ref().map(|config| serde_json::json!({
            "repository": config.repository,
            "baseCommit": config.base_commit,
            "allowedPaths": config.allowed_paths,
            "capabilities": config.capabilities,
            "qualityProfile": config.quality_profile,
        })),
        "existingProposal": context.proposal.as_ref().map(|proposal| serde_json::json!({
            "acceptanceCriteria": proposal.acceptance_criteria,
            "negativeCases": proposal.negative_cases,
            "assumptions": proposal.assumptions,
            "risks": proposal.risks,
        })),
        "limits": {
            "maxRequirements": factory_native::agentic::MAX_SPEC_REQUIREMENTS,
            "maxCasesPerRequirement": factory_native::agentic::MAX_SPEC_CASES,
        }
    })
    .to_string();
    let result = match call_agentic_lead_model(
        &app,
        &record,
        "agentic_spec_manager",
        &system_prompt,
        &user_prompt,
        AGENTIC_LEAD_STRUCTURED_OUTPUT_TOKENS,
    )
    .await
    {
        Ok(result) => result,
        Err(response) => return response,
    };
    let draft = match factory_native::model_output::decode_spec_draft(result.content.as_bytes()) {
        Ok(draft) => draft,
        Err(error) => {
            return (
                StatusCode::BAD_GATEWAY,
                Json(json!({
                    "error": error.to_string(),
                    "code": "AGENTIC_SPEC_OUTPUT_INVALID",
                })),
            )
                .into_response();
        }
    };
    let frozen = match factory_native::agentic::compile_spec(&draft, revision) {
        Ok(frozen) => frozen,
        Err(error) => {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({"error": error, "code": "AGENTIC_SPEC_INVALID"})),
            )
                .into_response();
        }
    };
    if let Err(error) = validate_spec_unit_mapping(&frozen, &graph) {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error": error, "code": "AGENTIC_SPEC_INVALID"})),
        )
            .into_response();
    }
    let draft_json = match serde_json::to_string(&draft) {
        Ok(json) => json,
        Err(_) => {
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "spec draft could not be encoded"})),
            )
                .into_response();
        }
    };
    match app
        .db
        .save_agentic_spec_draft(&factory_native::db::NewAgenticSpecDraft {
            request_id: &record.id,
            draft_json: &draft_json,
            graph_sha256: Some(&graph_record.graph_sha256),
            provider: &result.provider,
            model: &result.model,
            schema_sha256: &schema_sha256,
            request_sha256: &result.request_sha256,
            input_tokens: result.input_tokens,
            output_tokens: result.output_tokens,
            total_tokens: result.total_tokens,
            cost_micros: result.cost_micros,
            usage_known: result.usage_known,
        })
        .await
    {
        Ok(spec) => {
            let preview = factory_native::agentic::compile_spec(&draft, spec.revision).ok();
            if let Some(preview) = preview.as_ref()
                && let Err(response) =
                    persist_openspec_projection(&app, &record, preview, &graph).await
            {
                return response;
            }
            Json(json!({
                "spec": spec,
                "preview": preview,
                "provider": result.provider,
                "model": result.model,
                "usage": {
                    "inputTokens": result.input_tokens,
                    "outputTokens": result.output_tokens,
                    "totalTokens": result.total_tokens,
                    "costMicros": result.cost_micros,
                    "usageKnown": result.usage_known,
                }
            }))
            .into_response()
        }
        Err(error) => api_error(error),
    }
}

async fn freeze_agentic_spec(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    Json(input): Json<AgenticSpecFreezeRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    if input.expected_spec_sha256.len() != 64
        || !input
            .expected_spec_sha256
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit())
    {
        return api_error(Error::Invalid("expected spec sha256"));
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let draft = match app.db.agentic_spec_draft(&record.id).await {
        Ok(draft) => draft,
        Err(Error::NotFound) => {
            return agentic_conflict(
                "SPEC_DRAFT_REQUIRED",
                "there is no draft specification to freeze",
            );
        }
        Err(error) => return api_error(error),
    };
    let graph_record = match app.db.agentic_work_graph(&record.id).await {
        Ok(graph) => graph,
        Err(error) => return api_error(error),
    };
    let graph = match parse_graph_record(&graph_record) {
        Ok(graph) => graph,
        Err(response) => return *response,
    };
    let draft_model =
        match serde_json::from_str::<factory_native::agentic::SpecDraftModel>(&draft.draft_json) {
            Ok(draft) => draft,
            Err(_) => {
                return (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    Json(json!({"error": "stored spec draft is not decodable"})),
                )
                    .into_response();
            }
        };
    let frozen = match factory_native::agentic::compile_spec(&draft_model, draft.revision) {
        Ok(frozen) => frozen,
        Err(error) => {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({"error": error, "code": "AGENTIC_SPEC_INVALID"})),
            )
                .into_response();
        }
    };
    // The freeze path recompiles the stored draft, including legacy drafts
    // that predate the explicit mapping. Reapply the same membership and
    // coverage checks so an unmapped draft can never be frozen.
    if let Err(error) = validate_spec_unit_mapping(&frozen, &graph) {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error": error, "code": "AGENTIC_SPEC_INVALID"})),
        )
            .into_response();
    }
    if frozen.spec_sha256 != input.expected_spec_sha256 {
        return agentic_conflict(
            "SPEC_REVISION_CHANGED",
            "the draft specification changed; reload before freezing",
        );
    }
    match app.db.freeze_agentic_spec(&draft.id, &frozen, &graph).await {
        Ok(spec) => {
            let context = match agentic_triage_context(&app, &record).await {
                Ok(context) => context,
                Err(error) => return api_error(error),
            };
            if let Err(error) = try_freeze_approved_plan(&app, &record.id, &context).await {
                return api_error(error);
            }
            let workflow = app
                .db
                .workflow_run_for_request(&record.id)
                .await
                .ok()
                .flatten();
            Json(json!({"spec": spec, "frozen": frozen, "workflow": workflow})).into_response()
        }
        Err(error) => api_error(error),
    }
}

async fn publish_agentic_spec(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    Json(input): Json<AgenticSpecPublishRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    if !input.confirm {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({
                "error": "explicit confirmation is required before publishing spec issues",
                "code": "SPEC_PUBLISH_CONFIRMATION_REQUIRED",
            })),
        )
            .into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let spec = match app.db.agentic_spec(&record.id).await {
        Ok(spec) if spec.state == "FROZEN" => spec,
        Ok(_) => {
            return agentic_conflict(
                "SPEC_NOT_FROZEN",
                "only a frozen specification can be published",
            );
        }
        Err(Error::NotFound) => {
            return agentic_conflict(
                "SPEC_NOT_FROZEN",
                "there is no frozen specification to publish",
            );
        }
        Err(error) => return api_error(error),
    };
    let binding = app.db.project_github_binding(&record.project_id).await.ok();
    if input.local || binding.is_none() {
        let repository = binding
            .as_ref()
            .map(|binding| binding.repo_full_name.clone())
            .unwrap_or_else(|| "local-board".into());
        return match app
            .db
            .upsert_agentic_spec_publication(&factory_native::db::NewAgenticSpecPublication {
                spec_id: &spec.id,
                project_id: &record.project_id,
                provider: "LOCAL",
                repository: &repository,
                status: "LOCAL",
                drift_status: "UNKNOWN",
                last_error: None,
            })
            .await
        {
            Ok(publication) => Json(json!({
                "publication": publication,
                "issues": app.db.agentic_spec_issues(&spec.id).await.unwrap_or_default(),
                "local": true,
            }))
            .into_response(),
            Err(error) => api_error(error),
        };
    }
    let binding = binding.expect("binding checked");
    let credential = match load_github_credential(&app).await {
        Ok(credential) => credential,
        Err(response) => return response,
    };
    let _ = app
        .db
        .upsert_agentic_spec_publication(&factory_native::db::NewAgenticSpecPublication {
            spec_id: &spec.id,
            project_id: &record.project_id,
            provider: "GITHUB",
            repository: &binding.repo_full_name,
            status: "PENDING",
            drift_status: "UNKNOWN",
            last_error: None,
        })
        .await;
    match factory_native::spec_publish::publish_spec(
        &app.db,
        &app.github,
        &credential,
        &spec,
        &record.objective,
        &binding.owner,
        &binding.repo,
    )
    .await
    {
        Ok(issues) => match app
            .db
            .upsert_agentic_spec_publication(&factory_native::db::NewAgenticSpecPublication {
                spec_id: &spec.id,
                project_id: &record.project_id,
                provider: "GITHUB",
                repository: &binding.repo_full_name,
                status: "PUBLISHED",
                drift_status: "IN_SYNC",
                last_error: None,
            })
            .await
        {
            Ok(publication) => {
                Json(json!({"publication": publication, "issues": issues})).into_response()
            }
            Err(error) => api_error(error),
        },
        Err(error) => {
            let message = error.to_string();
            let _ = app
                .db
                .upsert_agentic_spec_publication(&factory_native::db::NewAgenticSpecPublication {
                    spec_id: &spec.id,
                    project_id: &record.project_id,
                    provider: "GITHUB",
                    repository: &binding.repo_full_name,
                    status: "FAILED",
                    drift_status: "UNKNOWN",
                    last_error: Some(&message),
                })
                .await;
            (
                StatusCode::BAD_GATEWAY,
                Json(json!({
                    "error": message,
                    "code": "SPEC_PUBLISH_FAILED",
                })),
            )
                .into_response()
        }
    }
}

async fn refresh_agentic_spec(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let spec = match app.db.agentic_spec(&record.id).await {
        Ok(spec) if spec.state == "FROZEN" => spec,
        _ => {
            return agentic_conflict(
                "SPEC_NOT_FROZEN",
                "there is no frozen specification to refresh",
            );
        }
    };
    let binding = match app.db.project_github_binding(&record.project_id).await {
        Ok(binding) => binding,
        Err(Error::NotFound) => {
            return agentic_conflict(
                "GITHUB_NOT_BOUND",
                "the project is not bound to a GitHub repository",
            );
        }
        Err(error) => return api_error(error),
    };
    let credential = match load_github_credential(&app).await {
        Ok(credential) => credential,
        Err(response) => return response,
    };
    let in_sync = match factory_native::spec_publish::refresh_publication(
        &app.db,
        &app.github,
        &credential,
        &spec,
        &binding.owner,
        &binding.repo,
    )
    .await
    {
        Ok(in_sync) => in_sync,
        Err(factory_native::spec_publish::SpecPublishError::GitHub(error)) => {
            return (
                StatusCode::BAD_GATEWAY,
                Json(json!({"error": error.to_string(), "code": "SPEC_REFRESH_FAILED"})),
            )
                .into_response();
        }
        Err(error) => {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({"error": error.to_string(), "code": "SPEC_REFRESH_INVALID"})),
            )
                .into_response();
        }
    };
    match app
        .db
        .upsert_agentic_spec_publication(&factory_native::db::NewAgenticSpecPublication {
            spec_id: &spec.id,
            project_id: &record.project_id,
            provider: "GITHUB",
            repository: &binding.repo_full_name,
            status: "PUBLISHED",
            drift_status: if in_sync { "IN_SYNC" } else { "DRIFTED" },
            last_error: None,
        })
        .await
    {
        Ok(publication) => {
            Json(json!({"publication": publication, "inSync": in_sync})).into_response()
        }
        Err(error) => api_error(error),
    }
}

async fn agentic_spec_board(State(app): State<Arc<App>>, headers: HeaderMap) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let specs = match app.db.frozen_agentic_specs().await {
        Ok(specs) => specs,
        Err(error) => return api_error(error),
    };
    let mut cards = Vec::with_capacity(specs.len());
    for spec in specs {
        let record = match app.db.intake_request(&spec.request_id).await {
            Ok(record) => record,
            Err(_) => continue,
        };
        let operation = app.db.agentic_operation_for_request(&record.id).await.ok();
        let publication = app.db.agentic_spec_publication(&spec.id).await.ok();
        let issues = app
            .db
            .agentic_spec_issues(&spec.id)
            .await
            .unwrap_or_default();
        let campaign_status = match &record.campaign_id {
            Some(campaign_id) => app.db.campaign_status_and_gate(campaign_id).await.ok(),
            None => None,
        };
        let gate = campaign_status.as_ref().and_then(|(_, gate)| gate.clone());
        let campaign = campaign_status.as_ref().map(|(status, _)| status.clone());
        let column = match (
            campaign.as_deref(),
            gate.as_deref(),
            operation
                .as_ref()
                .map(|operation| operation.status.as_str()),
        ) {
            (Some("CANCELLED"), _, _) => "CANCELLED",
            (Some("FAILED"), _, _)
            | (_, Some("REPAIR_REQUIRED" | "BLOCKED" | "HUMAN_REQUIRED" | "NOT_TESTED"), _) => {
                "BLOCKED"
            }
            (_, Some("ACCEPTED"), _) => "ACCEPTED",
            (Some(_), _, Some("EXECUTING" | "STARTING")) => "RUNNING",
            (Some(_), _, _) => "QUEUED",
            (None, _, _) => "FROZEN",
        };
        let graph = spec.graph_json.as_deref().and_then(|json| {
            serde_json::from_str::<factory_native::agentic::ValidatedWorkGraph>(json).ok()
        });
        let frozen = spec.frozen_json.as_deref().and_then(|json| {
            serde_json::from_str::<factory_native::agentic::FrozenSpec>(json).ok()
        });
        cards.push(json!({
            "specId": spec.id,
            "requestId": record.id,
            "projectId": record.project_id,
            "objective": record.objective,
            "revision": spec.revision,
            "summary": frozen.as_ref().map(|frozen| frozen.summary.clone()),
            "specSha256": spec.spec_sha256,
            "graphSha256": spec.graph_sha256,
            "frozenAt": spec.frozen_at,
            "column": column,
            "campaignStatus": campaign,
            "gateOutcome": gate,
            "operation": operation,
            "publication": publication,
            "issues": issues,
            "units": graph.map(|graph| graph.units).unwrap_or_default(),
        }));
    }
    Json(json!({
        "columns": ["FROZEN", "QUEUED", "RUNNING", "ACCEPTED", "BLOCKED", "CANCELLED"],
        "specs": cards,
    }))
    .into_response()
}

async fn explorer_inventory(
    app: &App,
    project: &factory_native::db::Project,
) -> Result<factory_native::knowledge::RepositoryInventory, Response> {
    let project_id = project.id.clone();
    let repository = PathBuf::from(project.repository.clone());
    let identity = project.identity.clone();
    let base_commit = project.base_commit.clone();
    let manifests = ["Cargo.toml", "package.json"];
    let mut inventories = Vec::new();
    for manifest in manifests {
        let project_id = project_id.clone();
        let repository = repository.clone();
        let identity = identity.clone();
        let base_commit = base_commit.clone();
        let path = manifest.to_owned();
        let result = tokio::task::spawn_blocking(move || {
            factory_native::project_files::read_project_file(
                &project_id,
                &repository,
                &identity,
                &base_commit,
                None,
                &path,
            )
        })
        .await;
        let Ok(Ok(projection)) = result else {
            continue;
        };
        let Some(content) = projection.content else {
            continue;
        };
        let libraries = if manifest.ends_with(".toml") {
            factory_native::knowledge::parse_cargo_manifest(&content, manifest)
        } else {
            factory_native::knowledge::parse_package_json(&content, manifest)
        };
        inventories.push((manifest.to_owned(), libraries));
    }
    let mut library_map = BTreeMap::new();
    for (manifest, libraries) in &inventories {
        for library in libraries {
            library_map
                .entry(library.name.to_ascii_lowercase())
                .or_insert_with(|| library.clone());
        }
        let _ = manifest;
    }
    let mut libraries = library_map.into_values().collect::<Vec<_>>();
    libraries.sort_by(|left, right| left.name.cmp(&right.name));
    let manifests = inventories
        .iter()
        .map(|(manifest, _)| manifest.clone())
        .collect::<Vec<_>>();
    let evidence_refs = if manifests.is_empty() {
        vec!["repository manifest inventory unavailable".into()]
    } else {
        manifests.clone()
    };
    let _ = app;
    Ok(factory_native::knowledge::RepositoryInventory {
        manifests,
        libraries,
        evidence_refs,
    })
}

async fn get_agentic_knowledge(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let pack = app.db.agentic_knowledge_pack(&record.id).await.ok();
    let skills = app
        .db
        .agentic_skills(Some(&record.project_id))
        .await
        .unwrap_or_default()
        .into_iter()
        .filter(|skill| skill.request_id.as_deref() == Some(record.id.as_str()))
        .collect::<Vec<_>>();
    let adoptions = app
        .db
        .agentic_skill_adoptions(&record.id)
        .await
        .unwrap_or_default();
    let project = app.db.project(&record.project_id).await.ok();
    let inventory = match project.as_ref() {
        Some(project) => explorer_inventory(&app, project).await.ok(),
        None => None,
    };
    Json(json!({
        "pack": pack,
        "skills": skills,
        "adoptions": adoptions,
        "inventory": inventory,
    }))
    .into_response()
}

async fn research_agentic_knowledge(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    Json(input): Json<AgenticKnowledgeRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let project = match app.db.project(&record.project_id).await {
        Ok(project) => project,
        Err(error) => return api_error(error),
    };
    let context = match agentic_triage_context(&app, &record).await {
        Ok(context) => context,
        Err(error) => return api_error(error),
    };
    let skill_needs = context
        .semantic
        .as_ref()
        .map(|(_, model)| model.skill_needs.clone())
        .unwrap_or_default();
    let inventory = match explorer_inventory(&app, &project).await {
        Ok(inventory) => inventory,
        Err(response) => return response,
    };
    let gap = match factory_native::knowledge::detect_knowledge_gap(
        &inventory,
        &record.objective,
        &skill_needs,
        &input.library,
        &input.query,
    ) {
        Ok(gap) => gap,
        Err(error) => {
            return (
                StatusCode::CONFLICT,
                Json(json!({
                    "error": error,
                    "code": "KNOWLEDGE_GAP_REQUIRED",
                })),
            )
                .into_response();
        }
    };
    let client = match factory_native::context7::Context7Client::production() {
        Ok(client) => client,
        Err(error) => {
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": error.to_string(), "code": "CONTEXT7_CONFIGURATION"})),
            )
                .into_response();
        }
    };
    let fetched_at = chrono::Utc::now().to_rfc3339();
    let pack = match client
        .knowledge_pack(&gap.library, &gap.query, &fetched_at)
        .await
    {
        Ok(pack) => pack,
        Err(error) => {
            return (
                StatusCode::BAD_GATEWAY,
                Json(json!({
                    "error": error.to_string(),
                    "code": "CONTEXT7_UNAVAILABLE",
                })),
            )
                .into_response();
        }
    };
    if pack.library_id.is_empty()
        || !pack.library_id.starts_with('/')
        || pack.sources.is_empty()
        || pack.pack_sha256.len() != 64
    {
        return (
            StatusCode::BAD_GATEWAY,
            Json(json!({
                "error": "Context7 returned an unusable KnowledgePack",
                "code": "CONTEXT7_INVALID",
            })),
        )
            .into_response();
    }
    let source_url = pack.sources[0].url.clone();
    let saved_pack = match app
        .db
        .save_agentic_knowledge_pack(&factory_native::db::NewAgenticKnowledgePack {
            request_id: &record.id,
            project_id: &record.project_id,
            pack: &pack,
            provider: "CONTEXT7_MCP",
            source_url: &source_url,
        })
        .await
    {
        Ok(pack) => pack,
        Err(error) => return api_error(error),
    };
    let created_at = chrono::Utc::now();
    let expires_at = (created_at + chrono::Duration::days(7)).to_rfc3339();
    let created_at = created_at.to_rfc3339();
    let manifest = match factory_native::knowledge::derive_skill_manifest(
        &pack,
        &context.stack.languages,
        &created_at,
        &expires_at,
    ) {
        Ok(manifest) => manifest,
        Err(error) => {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({"error": error, "code": "SKILL_MANIFEST_INVALID"})),
            )
                .into_response();
        }
    };
    if let Err(error) = factory_native::knowledge::trust_gate(
        &manifest,
        &["context-read".into(), "repository-read".into()],
        &created_at,
    ) {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error": error, "code": "SKILL_TRUST_GATE_REJECTED"})),
        )
            .into_response();
    }
    let manifest_sha256 = factory_native::knowledge::skill_manifest_sha256(&manifest);
    let skill = match app
        .db
        .create_agentic_skill(&factory_native::db::NewAgenticSkill {
            project_id: &record.project_id,
            request_id: &record.id,
            manifest: &manifest,
            manifest_sha256: &manifest_sha256,
            status: "ACTIVE",
        })
        .await
    {
        Ok(skill) => skill,
        Err(error) => return api_error(error),
    };
    if skill.manifest_sha256 != manifest_sha256 && skill.scope == "RUN" {
        return (
            StatusCode::CONFLICT,
            Json(json!({
                "error": "a temporary skill for this library already exists with different knowledge",
                "code": "SKILL_ALREADY_EXISTS",
            })),
        )
            .into_response();
    }
    Json(json!({
        "gap": gap,
        "pack": saved_pack,
        "skill": skill,
        "inventory": inventory,
    }))
    .into_response()
}

async fn agentic_skills(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    Query(query): Query<std::collections::HashMap<String, String>>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let project_id = query.get("project_id").map(String::as_str);
    let now = chrono::Utc::now().to_rfc3339();
    match app.db.agentic_skills(project_id).await {
        Ok(skills) => {
            let values = skills
                .into_iter()
                .map(|skill| {
                    let review_due = skill
                        .next_review_at
                        .as_deref()
                        .is_some_and(|value| value <= now.as_str());
                    json!({
                        "skill": skill,
                        "reviewDue": review_due,
                    })
                })
                .collect::<Vec<_>>();
            Json(json!({"skills": values})).into_response()
        }
        Err(error) => api_error(error),
    }
}

