#[derive(Deserialize, Default)]
struct TraceQuery {
    limit: Option<usize>,
}

async fn agentic_request_trace(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    Query(query): Query<TraceQuery>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    #[cfg(feature = "test-support")]
    if let Some(response) = wave12_support::trace_intercept(&id).await {
        return response;
    }
    if let Err(error) = app.db.intake_request(&id).await {
        return api_error(error);
    }
    let limit = query
        .limit
        .unwrap_or(factory_native::trace::TRACE_EVENT_DEFAULT);
    match app.db.workflow_trace(&id, limit).await {
        Ok(view) => Json(view).into_response(),
        Err(error) => api_error(error),
    }
}

fn internal_operator_headers(app: &App) -> HeaderMap {
    let mut headers = HeaderMap::new();
    headers.insert(
        header::AUTHORIZATION,
        format!("Bearer {}", app.operator_token)
            .parse()
            .expect("operator token header"),
    );
    headers
}

/// Record the request-scoped subscription funding admission required by the
/// assessment/model calls. This is funding evidence only: it never authorizes a
/// Campaign start, and every start still passes the planning-readiness guard
/// plus the frozen policy, scope and exact-binding checks.
async fn ensure_autopilot_subscription_admission(app: &Arc<App>, id: &str) -> Result<(), Error> {
    if app
        .db
        .active_subscription_admission_for_request(id)
        .await?
        .is_some()
    {
        return Ok(());
    }
    let now = chrono::Utc::now().timestamp_millis();
    let input = IntakeSubscriptionAdmissionRequest {
        assumption_id: format!("lead-autopilot:{id}:{now}"),
        confirmed_by: "Product Owner (autonomous R0 policy)".into(),
        confirmed_at_ms: now - 1_000,
        valid_until_ms: now + 24 * 60 * 60 * 1_000,
        extra_usage_disabled: true,
        statement:
            "Owner confirmed OpenCode Go Extra Usage is OFF and authorized autonomous R0 subscription execution."
                .into(),
        test_profile_id: "opencode-go-subscription".into(),
        // The admission can expire while an autonomous request is still
        // unfinished. A time-scoped key lets a resume create a fresh active
        // admission instead of replaying expired evidence.
        idempotency_key: format!("lead-autopilot-admission:{id}:{now}"),
    };
    let response = create_intake_subscription_admission(
        State(Arc::clone(app)),
        internal_operator_headers(app),
        AxumPath(id.to_owned()),
        None,
        Json(input),
    )
    .await;
    if !response.status().is_success() {
        return Err(Error::IntakeConflict {
            code: "AUTOPILOT_SUBSCRIPTION_ADMISSION_FAILED",
            message: format!(
                "autopilot could not record the subscription admission: {}",
                response.status()
            ),
        });
    }
    Ok(())
}

async fn autonomous_start_intake(app: &Arc<App>, id: &str) -> Result<(), Error> {
    let context = app.db.intake_start_context(id).await?;
    if context.lead.campaign_id.is_some() {
        return Ok(());
    }
    ensure_planning_ready_or_error(app, &context.intake).await?;
    let global_reserved = factory_native::db::RESERVED_MATTERS
        .iter()
        .map(|matter| (*matter).to_string())
        .collect::<Vec<_>>();
    if let Some(matter) = reserved_matter_triggered(&context.lead.objective, &global_reserved) {
        return Err(Error::Forbidden(format!(
            "autonomous execution of reserved matter {matter} requires an explicit owner decision"
        )));
    }
    if let Ok(Some(charter)) = app
        .db
        .active_agentic_charter(&context.intake.project_id)
        .await
    {
        let risk = app
            .db
            .lead_proposal(&context.lead.id)
            .await
            .ok()
            .and_then(|record| {
                serde_json::from_str::<factory_native::lead::LeadPlanProposal>(
                    &record.proposal_json,
                )
                .ok()
            })
            .map(|proposal| proposal.risk_class)
            .unwrap_or(factory_native::lead::RiskClass::R0);
        let reserved =
            reserved_matter_triggered(&context.lead.objective, &charter.reserved_matters);
        if !charter.domains.iter().any(|domain| domain == "repository") {
            return Err(Error::Forbidden(
                "the owner charter does not cover the repository execution domain".into(),
            ));
        }
        if !charter.execution_autonomy || risk > charter.risk_appetite || reserved.is_some() {
            return Err(Error::Forbidden(
                "autonomous execution requires an explicit owner decision under the active charter"
                    .into(),
            ));
        }
    }
    let billable = context.mechanism == "MODEL";
    let admission_id = if billable {
        let admission = app.db.active_subscription_admission_for_request(id).await?;
        if admission.is_none() {
            return Err(Error::IntakeConflict {
                code: "SUBSCRIPTION_ADMISSION_REQUIRED",
                message:
                    "autonomous MODEL start requires the request-scoped subscription admission"
                        .into(),
            });
        }
        admission
    } else {
        None
    };
    let authorization = build_intake_authorization(
        &context,
        Some("Lead (autopilot)"),
        "lead-autopilot",
        "Autonomous R0 start under the owner-granted execution policy",
        factory_native::db::NO_BILLABLE_ENVELOPE,
    );
    let expected = factory_native::db::ExpectedStartBinding::new(
        &context.lead.request_hash,
        &context.plan.plan_hash,
        &context.spec_sha256,
        &context.lead.project_config_hash,
        &context.grant.content_hash,
        Some(&context.context.profile_revision_id),
        Some(&context.context.profile_hash),
    )?;
    let autonomy = factory_native::db::ValidatedAutonomyContext::from_deployment_policy(
        app.lead_autonomous_start,
    )?;
    let idempotency_key = format!("intake-autopilot:{id}:{}", context.plan.plan_hash);
    app.db
        .start_lead_campaign_with_admission(
            &context.lead.id,
            &idempotency_key,
            factory_native::db::StartAuthority::Autonomous(autonomy),
            Some(&expected),
            Some(&authorization),
            admission_id.as_deref(),
        )
        .await?;
    Ok(())
}

#[derive(Clone)]
struct QueuedOperation {
    priority: i64,
    sequence: u64,
    request_id: String,
}

struct AgenticScheduler {
    queue: tokio::sync::Mutex<Vec<QueuedOperation>>,
    notify: tokio::sync::Notify,
    permits: Arc<tokio::sync::Semaphore>,
    active: AtomicUsize,
    capacity: usize,
    sequence: AtomicUsize,
}

static AGENTIC_SCHEDULER: OnceLock<Arc<AgenticScheduler>> = OnceLock::new();

/// Resource-derived start concurrency. This is not a fixed product cap: the
/// number of simultaneous Lead assessment/start operations is bounded by the
/// observed CPU and available memory, with worker/Campaign concurrency governed
/// separately by leases and the worker runtime.
fn agentic_start_capacity() -> usize {
    let cpu = std::thread::available_parallelism()
        .map(std::num::NonZeroUsize::get)
        .unwrap_or(2);
    let memory_slots = std::fs::read_to_string("/proc/meminfo")
        .ok()
        .and_then(|contents| {
            contents
                .lines()
                .find(|line| line.starts_with("MemAvailable:"))
                .and_then(|line| line.split_whitespace().nth(1))
                .and_then(|value| value.parse::<u64>().ok())
        })
        .map(|available_kb| usize::try_from(available_kb / (2 * 1024 * 1024)).unwrap_or(1))
        .unwrap_or(2)
        .max(1);
    cpu.min(memory_slots).max(1)
}

fn start_agentic_scheduler(app: &Arc<App>) -> Arc<AgenticScheduler> {
    AGENTIC_SCHEDULER
        .get_or_init(|| {
            let capacity = agentic_start_capacity();
            let scheduler = Arc::new(AgenticScheduler {
                queue: tokio::sync::Mutex::new(Vec::new()),
                notify: tokio::sync::Notify::new(),
                permits: Arc::new(tokio::sync::Semaphore::new(capacity)),
                active: AtomicUsize::new(0),
                capacity,
                sequence: AtomicUsize::new(0),
            });
            let app_for_loop = Arc::clone(app);
            let scheduler_for_loop = Arc::clone(&scheduler);
            tokio::spawn(async move {
                agentic_scheduler_loop(app_for_loop, scheduler_for_loop).await;
            });
            scheduler
        })
        .clone()
}

impl AgenticScheduler {
    async fn enqueue(&self, request_id: &str, priority: i64) {
        let mut queue = self.queue.lock().await;
        if queue.iter().any(|item| item.request_id == request_id) {
            return;
        }
        queue.push(QueuedOperation {
            priority,
            sequence: self.sequence.fetch_add(1, Ordering::Relaxed) as u64,
            request_id: request_id.to_owned(),
        });
        drop(queue);
        self.notify.notify_waiters();
    }

    async fn reprioritize(&self, request_id: &str, priority: i64) {
        let mut queue = self.queue.lock().await;
        if let Some(item) = queue.iter_mut().find(|item| item.request_id == request_id) {
            item.priority = priority;
        }
    }

    async fn next(&self) -> QueuedOperation {
        loop {
            let mut queue = self.queue.lock().await;
            queue.sort_by_key(|item| (item.priority, item.sequence));
            if let Some(item) = queue.pop() {
                return item;
            }
            drop(queue);
            self.notify.notified().await;
        }
    }
}

async fn enqueue_autopilot(app: &Arc<App>, request_id: &str) {
    let priority = app
        .db
        .agentic_operation_for_request(request_id)
        .await
        .map(|operation| operation.priority)
        .unwrap_or(100);
    start_agentic_scheduler(app)
        .enqueue(request_id, priority)
        .await;
}

async fn agentic_scheduler_loop(app: Arc<App>, scheduler: Arc<AgenticScheduler>) {
    loop {
        let permit = match Arc::clone(&scheduler.permits).acquire_owned().await {
            Ok(permit) => permit,
            Err(_) => return,
        };
        let item = scheduler.next().await;
        scheduler.active.fetch_add(1, Ordering::Relaxed);
        let app_for_task = Arc::clone(&app);
        let scheduler_for_task = Arc::clone(&scheduler);
        tokio::spawn(async move {
            let _permit = permit;
            // STARTING is scheduler/operation telemetry, not Campaign authority.
            // A Campaign is created only inside the frozen start transaction
            // after readiness, policy, scope and exact-binding checks.
            let _ = app_for_task
                .db
                .set_agentic_operation_status(&item.request_id, "STARTING")
                .await;
            if let Err(error) = run_autopilot(&app_for_task, &item.request_id).await {
                fail_autopilot(&app_for_task, &item.request_id, &error).await;
                let _ = app_for_task
                    .db
                    .set_agentic_operation_status(&item.request_id, "BLOCKED")
                    .await;
            }
            scheduler_for_task.active.fetch_sub(1, Ordering::Relaxed);
            scheduler_for_task.notify.notify_waiters();
        });
    }
}

async fn run_autopilot(app: &Arc<App>, id: &str) -> Result<(), Error> {
    {
        let mut in_flight = app.autopilot_in_flight.lock().await;
        if !in_flight.insert(id.to_owned()) {
            return Ok(());
        }
    }
    let result = run_autopilot_inner(app, id).await;
    app.autopilot_in_flight.lock().await.remove(id);
    result
}

async fn run_autopilot_inner(app: &Arc<App>, id: &str) -> Result<(), Error> {
    let record = app.db.intake_request(id).await?;
    if record.mode != factory_native::intake::IntakeMode::Autonomous {
        return Ok(());
    }
    let policy = app.db.execution_policy_grant(&record.delegation_id).await?;
    let profile = app
        .db
        .execution_profile_revision(&record.profile_id, &record.profile_revision_id)
        .await?;
    let subscription_profile = profile
        .content
        .v2()
        .is_some_and(factory_native::intake::autonomous_subscription_profile);
    if !policy.autonomous || !policy.subscription_confirmed || !subscription_profile {
        return Err(Error::IntakeConflict {
            code: "AUTONOMOUS_POLICY_REQUIRED",
            message:
                "autonomous intake requires the owner-granted autonomous R0 policy with subscription confirmation and OpenCode Go subscription routes for the Lead and implementer"
                    .into(),
        });
    }
    // The subscription admission is funding evidence for assessment/provider
    // calls. It never authorizes a Campaign start; that requires the frozen
    // readiness guard and the exact start transaction below.
    ensure_autopilot_subscription_admission(app, id).await?;
    let response = assess_intake_request(
        State(Arc::clone(app)),
        internal_operator_headers(app),
        AxumPath(id.to_owned()),
    )
    .await;
    if !response.status().is_success() && response.status() != StatusCode::CONFLICT {
        return Err(Error::IntakeConflict {
            code: "AUTOPILOT_ASSESSMENT_FAILED",
            message: format!("autopilot assessment returned {}", response.status()),
        });
    }
    let record = app.db.intake_request(id).await?;
    let lead = app.db.lead_request(&record.lead_request_id).await?;
    if lead.campaign_id.is_some() {
        let _ = app.db.set_agentic_operation_status(id, "EXECUTING").await;
        return Ok(());
    }
    // Re-check immediately before the start call so an incomplete plan becomes
    // a truthful autopilot blocker instead of a doomed Campaign.
    ensure_planning_ready_or_error(app, &record).await?;
    autonomous_start_intake(app, id).await?;
    let _ = app.db.set_agentic_operation_status(id, "EXECUTING").await;
    Ok(())
}

async fn fail_autopilot(app: &Arc<App>, id: &str, error: &Error) {
    tracing::warn!(%error, request_id = %id, "autopilot failed");
    if let Ok(record) = app.db.intake_request(id).await
        && record.campaign_id.is_none()
    {
        let _ = app
            .db
            .block_lead_request(&record.lead_request_id, &format!("autopilot: {error}"))
            .await;
    }
}

async fn resume_autopilot_requests(app: &Arc<App>) {
    let Ok(records) = app.db.unfinished_autonomous_intake_requests().await else {
        return;
    };
    for record in records {
        enqueue_autopilot(app, &record.id).await;
    }
}

async fn promote_accepted_repairs(app: Arc<App>) {
    loop {
        let _ = app.db.reconcile_agentic_operations().await;
        if let Ok(candidates) = app.db.accepted_repair_candidates().await {
            let mut advanced = BTreeSet::new();
            for (project_id, candidate_commit) in candidates {
                if !advanced.insert((project_id.clone(), candidate_commit.clone())) {
                    continue;
                }
                let Ok(config) = app.db.project_config(&project_id).await else {
                    continue;
                };
                if config.base_commit == candidate_commit {
                    continue;
                }
                let _ = app
                    .db
                    .advance_project_base_for_repair(
                        &project_id,
                        &candidate_commit,
                        config.revision,
                    )
                    .await;
            }
        }
        tokio::time::sleep(std::time::Duration::from_secs(5)).await;
    }
}

async fn create_intake_request(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    session: Option<Extension<factory_native::db::DeviceSessionRecord>>,
    Json(input): Json<NewIntakeRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let (principal_id, _) =
        authenticated_operator(session.as_ref().map(|Extension(device)| device));
    let selected_issues = match input.issue_selection() {
        Ok(selection) => selection,
        Err(error) => return api_error(error),
    };
    match app
        .db
        .create_intake_request_with_environment(
            &input.project_id,
            &input.objective,
            input.execution_profile_id.as_deref(),
            input.mode,
            &input.idempotency_key,
            &principal_id,
            &selected_issues,
            input.environment_constraints.as_ref(),
        )
        .await
    {
        Ok((record, created)) => {
            if let Some(authorized_micros) = input.authorized_micros {
                let profile = match app
                    .db
                    .execution_profile_revision(&record.profile_id, &record.profile_revision_id)
                    .await
                {
                    Ok(profile) => profile,
                    Err(error) => return api_error(error),
                };
                let Some(content) = profile.content.v2() else {
                    return api_error(Error::IntakeConflict {
                        code: "EXECUTION_PROFILE_NOT_EXECUTABLE",
                        message: "a legacy V1 execution profile cannot request billable inference"
                            .into(),
                    });
                };
                if let Err(error) =
                    ensure_profile_pricing_quotes(&app, content, &principal_id).await
                {
                    return api_error(error);
                }
                if let Err(error) = ensure_request_inference_envelope(
                    &app,
                    &record.id,
                    &record.project_id,
                    Some(authorized_micros),
                    &principal_id,
                    &request_scope_digest(&[
                        "intake-request-scope",
                        &record.project_id,
                        &record.profile_id,
                        &record.profile_revision_id,
                        &record.profile_hash,
                    ]),
                    &record.submission_hash,
                )
                .await
                {
                    return api_error(error);
                }
            }
            let value = match intake_request_value(&app, &record, true).await {
                Ok(value) => value,
                Err(error) => return api_error(error),
            };
            if created && record.mode == factory_native::intake::IntakeMode::Autonomous {
                enqueue_autopilot(&app, &record.id).await;
            }
            (
                if created {
                    StatusCode::CREATED
                } else {
                    StatusCode::OK
                },
                Json(value),
            )
                .into_response()
        }
        Err(Error::IntakeConflict { code, message })
            if matches!(
                code,
                "EXECUTION_POLICY_REQUIRED"
                    | "AUTONOMOUS_POLICY_REQUIRED"
                    | "SUBSCRIPTION_CONFIRMATION_REQUIRED"
            ) =>
        {
            let scope = intake_policy_scope(
                &app,
                &input.project_id,
                input.execution_profile_id.as_deref(),
            )
            .await;
            (
                StatusCode::CONFLICT,
                Json(json!({
                    "error": message,
                    "code": code,
                    "authorization": {
                        "required": true,
                        "available": false,
                        "reason": code,
                    },
                    "scope": scope,
                })),
            )
                .into_response()
        }
        Err(error) => api_error(error),
    }
}

#[cfg(feature = "test-support")]
async fn admit_test_subscription_dispatch(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    Json(input): Json<TestSubscriptionDispatchAdmission>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    match app.db.admit_test_subscription_dispatch(&input.scope).await {
        Ok(()) => StatusCode::NO_CONTENT.into_response(),
        Err(error) => api_error(error),
    }
}

async fn assess_intake_request(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    let lead = match app.db.lead_request(&record.lead_request_id).await {
        Ok(lead) => lead,
        Err(error) => return api_error(error),
    };
    if let Some(campaign_id) = &lead.campaign_id {
        let status = match app.db.campaign_status_and_gate(campaign_id).await {
            Ok((status, _)) => status,
            Err(error) => return api_error(error),
        };
        return api_error(Error::AlreadyStarted {
            campaign_id: campaign_id.clone(),
            campaign_status: status,
        });
    }
    if app
        .db
        .lead_withdrawal(&lead.id)
        .await
        .ok()
        .flatten()
        .is_some()
    {
        return api_error(Error::IntakeConflict {
            code: "INTAKE_WITHDRAWN",
            message: "the request was withdrawn; assessment and start are fenced".into(),
        });
    }
    match lead.state {
        LeadRequestState::Ready | LeadRequestState::Frozen => {
            return match intake_request_value(&app, &record, true).await {
                Ok(value) => Json(value).into_response(),
                Err(error) => api_error(error),
            };
        }
        LeadRequestState::Planned => {
            if let Err(error) = validate_intake_assess_authority(&app, &record, &lead).await {
                return api_error(error);
            }
            match app.db.lead_proposal(&lead.id).await {
                Ok(_) => {}
                Err(Error::NotFound) => {
                    return api_error(Error::IntakeConflict {
                        code: "ASSESSMENT_INCOMPLETE",
                        message:
                            "the assessment was recorded without a proposal; submit a new request"
                                .into(),
                    });
                }
                Err(error) => return api_error(error),
            }
            let (plan, _) = match app
                .db
                .freeze_lead_plan_to_ready(&lead.id, &format!("intake-assess:{id}:freeze"))
                .await
            {
                Ok(result) => result,
                Err(error) => return api_error(error),
            };
            let context = match app.db.intake_approval_context(&id).await {
                Ok(context) => context,
                Err(error) => return api_error(error),
            };
            if factory_native::intake::validate_execution_scope(
                &context.profile,
                &context.proposal,
                &context.grant,
                &context.intake.mode,
            )
            .is_err()
            {
                return api_error(Error::IntakeConflict {
                    code: "AUTHORIZATION_UNAVAILABLE_SCOPE",
                    message: "the frozen plan cannot be bound to the execution scope".into(),
                });
            }
            let _ = plan;
            return match intake_request_value(&app, &record, true).await {
                Ok(value) => Json(value).into_response(),
                Err(error) => api_error(error),
            };
        }
        LeadRequestState::Submitted => {}
        LeadRequestState::Assessing => {
            return api_error(Error::IntakeConflict {
                code: "ASSESSMENT_OUTCOME_UNKNOWN",
                message: "an assessment is in progress or its upstream outcome is unknown; do not retry silently"
                    .into(),
            });
        }
        LeadRequestState::Running | LeadRequestState::Blocked | LeadRequestState::Failed => {
            return api_error(Error::IntakeConflict {
                code: "ASSESSMENT_NOT_AVAILABLE",
                message: "the request is not in an assessable state".into(),
            });
        }
    }
    let profile = match validate_intake_assess_authority(&app, &record, &lead).await {
        Ok(profile) => profile,
        Err(error) => return api_error(error),
    };
    let Some(profile_content) = profile.content.v2() else {
        return api_error(Error::IntakeConflict {
            code: "EXECUTION_PROFILE_NOT_EXECUTABLE",
            message: "a legacy V1 execution profile cannot start billable assessment".into(),
        });
    };
    let gateway = match app.intake_assess_gateway(&profile).await {
        Ok(gateway) => gateway,
        Err(route_error) => {
            return (
                StatusCode::SERVICE_UNAVAILABLE,
                Json(json!({
                    "error": route_error.to_string(),
                    "code": "ASSESSMENT_UNAVAILABLE",
                    "routeCode": route_error.code(),
                })),
            )
                .into_response();
        }
    };
    let subscription_assessment = match app
        .db
        .subscription_scope_admitted(&record.id, gateway.provider(), gateway.model())
        .await
    {
        Ok(admitted) => admitted,
        Err(error) => return api_error(error),
    } || match app
        .db
        .subscription_scope_admitted(&record.lead_request_id, gateway.provider(), gateway.model())
        .await
    {
        Ok(admitted) => admitted,
        Err(error) => return api_error(error),
    };
    if !subscription_assessment {
        match app.db.inference_envelope_for_request(&id).await {
            Ok(Some(_)) => {}
            Ok(None) => {
                return api_error(Error::IntakeConflict {
                    code: "INFERENCE_AUTHORIZATION_REQUIRED",
                    message:
                        "the subscription route requires an exact Owner-confirmed subscription admission before assessment"
                            .into(),
                });
            }
            Err(error) => return api_error(error),
        }
        if let Err(error) =
            ensure_profile_pricing_quotes(&app, profile_content, "intake-assessment").await
        {
            return api_error(error);
        }
    }
    let action_spec = match app.db.intake_assessment_spec(&id).await {
        Ok(spec) => spec,
        Err(error) => return api_error(error),
    };
    let config = match app.db.project_config(&record.project_id).await {
        Ok(config) => config,
        Err(error) => return api_error(error),
    };
    let grant = match app.db.standing_delegation_v2(&record.delegation_id).await {
        Ok(grant) => grant,
        Err(error) => return api_error(error),
    };
    let action_binding = factory_native::lead::ActionBinding {
        id: record.action_id.clone(),
        project_id: record.project_id.clone(),
        status: factory_native::lead::ActionStatus::Pending,
    };
    if let Err(error) = app.db.begin_lead_assessment(&lead.id).await {
        return api_error(error);
    }
    let greenfield = agentic_stack_for_project(&app, &record.project_id)
        .await
        .languages
        .is_empty();
    let (assessment, proposal) = match factory_native::lead_model::assess(
        &gateway,
        &app.db,
        factory_native::lead_model::AssessmentRequest {
            request_id: &lead.id,
            project: &config,
            action: &action_binding,
            action_spec: &action_spec,
            objective: &lead.objective,
            grant: &grant,
            now: chrono::Utc::now(),
            greenfield,
        },
    )
    .await
    {
        Ok(value) => value,
        Err(factory_native::lead::LeadError::TransientAssessment(message)) => {
            return (
                StatusCode::SERVICE_UNAVAILABLE,
                Json(json!({
                    "error": message,
                    "code": "ASSESSMENT_TRANSIENT",
                })),
            )
                .into_response();
        }
        Err(error) => {
            let _ = app
                .db
                .block_lead_request(&lead.id, &error.to_string())
                .await;
            return api_error(error.into());
        }
    };
    let input = factory_native::lead::AssessmentInput {
        project_id: record.project_id.clone(),
        action_id: record.action_id.clone(),
        request_id: lead.id.clone(),
        objective: lead.objective.clone(),
        allowed_evidence_refs: std::collections::BTreeSet::from(["repository-files".to_string()]),
    };
    if let Err(error) = app
        .db
        .record_lead_assessment(
            &lead.id,
            "MODEL",
            &assessment,
            &input,
            &format!("intake-assess:{id}:assessment"),
        )
        .await
    {
        return api_error(error);
    }
    let Some(proposal) = proposal else {
        let _ = app
            .db
            .block_lead_request(
                &lead.id,
                "informational_assessment: no execution plan is required for this intent",
            )
            .await;
        return match intake_request_value(&app, &record, true).await {
            Ok(value) => Json(value).into_response(),
            Err(error) => api_error(error),
        };
    };
    if let Err(error) = app
        .db
        .record_lead_proposal(&lead.id, &proposal, &format!("intake-assess:{id}:proposal"))
        .await
    {
        return api_error(error);
    }
    if let Err(error) = validate_intake_assess_authority(&app, &record, &lead).await {
        let _ = app
            .db
            .block_lead_request(&lead.id, &error.to_string())
            .await;
        return api_error(error);
    }
    if let Err(error) = app
        .db
        .freeze_lead_plan_to_ready(&lead.id, &format!("intake-assess:{id}:freeze"))
        .await
    {
        return api_error(error);
    }
    match intake_request_value(&app, &record, true).await {
        Ok(value) => Json(value).into_response(),
        Err(error) => api_error(error),
    }
}

fn test_transport_for_provider(provider: &str) -> Option<&'static str> {
    match provider {
        // Codex is not admitted until Core can verify the ChatGPT credential
        // class and the native App Server transport owns the egress route.
        "opencode-go" => Some("OPENCODE_GO_SUBSCRIPTION"),
        _ => None,
    }
}

async fn create_intake_subscription_admission(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    session: Option<Extension<factory_native::db::DeviceSessionRecord>>,
    Json(input): Json<IntakeSubscriptionAdmissionRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    if !input.extra_usage_disabled {
        return api_error(Error::Forbidden(
            "Owner must confirm Extra Usage is disabled".into(),
        ));
    }
    if input.test_profile_id.trim().is_empty() {
        return api_error(Error::Forbidden(
            "subscription admission requires an admission profile".into(),
        ));
    }
    let (principal_id, _) =
        authenticated_operator(session.as_ref().map(|Extension(device)| device));
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    if record.campaign_id.is_some() {
        return api_error(Error::Conflict("intake request already has a Campaign"));
    }
    let profile = match app
        .db
        .execution_profile_revision(&record.profile_id, &record.profile_revision_id)
        .await
    {
        Ok(profile) => profile,
        Err(error) => return api_error(error),
    };
    let Some(content) = profile.content.v2() else {
        return api_error(Error::Forbidden(
            "subscription acceptance requires a V2 execution profile".into(),
        ));
    };
    // Bind the admission to the frozen profile Lead route, not the deployment
    // default. A profile can select a different Lead provider/model than the
    // default gateway, and the assessment must be covered by the exact route.
    let gateway = match app.intake_assess_gateway(&profile).await {
        Ok(gateway) => gateway,
        Err(route_error) => {
            return (
                StatusCode::SERVICE_UNAVAILABLE,
                Json(json!({
                    "error": route_error.to_string(),
                    "code": "ASSESSMENT_UNAVAILABLE",
                    "routeCode": route_error.code(),
                })),
            )
                .into_response();
        }
    };
    let assessment_provider = gateway.provider().to_owned();
    let assessment_model = gateway.model().to_owned();
    let Some(assessment_transport) = test_transport_for_provider(&assessment_provider) else {
        return api_error(Error::Forbidden(
            "assessment provider is outside the automated acceptance allowlist".into(),
        ));
    };
    let implementer = &content.roles.implementer;
    let Some(implementer_transport) = test_transport_for_provider(&implementer.provider) else {
        return api_error(Error::Forbidden(
            "implementer provider is outside the automated acceptance allowlist".into(),
        ));
    };
    let implementer_settings = match app.db.provider_settings(&implementer.provider).await {
        Ok(settings) if settings.enabled && !settings.credential_ciphertext.is_empty() => settings,
        Ok(_) => {
            return api_error(Error::Forbidden(
                "implementer provider is not configured and enabled".into(),
            ));
        }
        Err(error) => return api_error(error),
    };
    let assessment_settings = match app.db.provider_settings(&assessment_provider).await {
        Ok(settings) if settings.enabled && !settings.credential_ciphertext.is_empty() => settings,
        Ok(_) => {
            return api_error(Error::Forbidden(
                "assessment provider is not configured and enabled".into(),
            ));
        }
        Err(error) => return api_error(error),
    };
    if assessment_provider == "opencode-go"
        && !factory_native::provider_catalog::is_canonical_opencode_go_base_url(
            &assessment_settings.base_url,
        )
        && !factory_native::provider_catalog::is_test_upstream_url(&assessment_settings.base_url)
    {
        return api_error(Error::Forbidden(
            "OpenCode Go assessment must use the canonical subscription endpoint".into(),
        ));
    }
    let mut routes = vec![
        factory_native::subscription_admission::TestRouteBinding {
            role: factory_native::subscription_admission::TestModelRole::Lead,
            provider: assessment_provider.clone(),
            model: assessment_model.clone(),
            settings_revision: assessment_settings.revision.to_string(),
            transport: assessment_transport.to_owned(),
        },
        factory_native::subscription_admission::TestRouteBinding {
            role: factory_native::subscription_admission::TestModelRole::Implementer,
            provider: implementer.provider.clone(),
            model: implementer.model.clone(),
            settings_revision: implementer_settings.revision.to_string(),
            transport: implementer_transport.to_owned(),
        },
    ];
    let reviewer = &content.roles.semantic_reviewer;
    if reviewer.provider == "opencode-go" {
        let Some(reviewer_transport) = test_transport_for_provider(&reviewer.provider) else {
            return api_error(Error::Forbidden(
                "semantic reviewer provider is outside the automated acceptance allowlist".into(),
            ));
        };
        let reviewer_settings = match app.db.provider_settings(&reviewer.provider).await {
            Ok(settings) if settings.enabled && !settings.credential_ciphertext.is_empty() => {
                settings
            }
            Ok(_) => {
                return api_error(Error::Forbidden(
                    "semantic reviewer provider is not configured and enabled".into(),
                ));
            }
            Err(error) => return api_error(error),
        };
        routes.push(factory_native::subscription_admission::TestRouteBinding {
            role: factory_native::subscription_admission::TestModelRole::SemanticReviewer,
            provider: reviewer.provider.clone(),
            model: reviewer.model.clone(),
            settings_revision: reviewer_settings.revision.to_string(),
            transport: reviewer_transport.to_owned(),
        });
    }
    let assumption = factory_native::execution_policy::OwnerBillingAssumption {
        assumption_id: input.assumption_id,
        confirmed_by: format!("{principal_id}:{}", input.confirmed_by),
        confirmed_at_ms: input.confirmed_at_ms,
        valid_until_ms: input.valid_until_ms,
        extra_usage: factory_native::execution_policy::OwnerControlledExtraUsage::Disabled,
        statement: input.statement,
    };
    if assumption
        .validate_at(chrono::Utc::now().timestamp_millis())
        .is_err()
    {
        return api_error(Error::Invalid(
            "Owner billing assumption is invalid or expired",
        ));
    }
    let write = factory_native::db::ScopeAdmissionWrite {
        intake_request_id: record.id.clone(),
        lead_request_id: record.lead_request_id.clone(),
        test_profile_id: input.test_profile_id,
        execution_profile_id: record.profile_id.clone(),
        provider: assessment_provider,
        model: assessment_model,
        settings_revision: format!("model-gateway:{}:{}", gateway.provider(), gateway.model()),
        profile_revision_id: record.profile_revision_id.clone(),
        profile_hash: record.profile_hash.clone(),
        assumption,
        routes,
        idempotency_key: input.idempotency_key,
    };
    match app.db.create_subscription_scope_admission(&write).await {
        Ok(record) => Json(record).into_response(),
        Err(error) => api_error(error),
    }
}

async fn approve_intake_request(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    session: Option<Extension<factory_native::db::DeviceSessionRecord>>,
    Json(input): Json<ApproveIntakeRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let (principal_id, device_label) =
        authenticated_operator(session.as_ref().map(|Extension(device)| device));
    let principal_label = input.principal_label.as_deref().or(device_label.as_deref());
    if input.expected_plan_hash.len() != 64
        || !input
            .expected_plan_hash
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit())
    {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error":"expected_plan_hash must be a SHA-256 hex digest"})),
        )
            .into_response();
    }
    let approval = match factory_native::db::AuthenticatedOperatorApproval::new(
        &principal_id,
        principal_label,
        &input.rationale,
    ) {
        Ok(approval) => approval,
        Err(error) => return api_error(error),
    };
    let context = match app.db.intake_start_context(&id).await {
        Ok(context) => context,
        Err(error) => return api_error(error),
    };
    if context.plan.plan_hash != input.expected_plan_hash {
        return api_error(Error::IntakeConflict {
            code: "PLAN_HASH_MISMATCH",
            message: "the expected plan hash does not identify the frozen plan".into(),
        });
    }
    if let Some(expected_profile_revision_id) = &input.expected_profile_revision_id
        && expected_profile_revision_id != &context.context.profile_revision_id
    {
        return api_error(Error::IntakeConflict {
            code: "PROFILE_REVISION_MISMATCH",
            message: "the expected profile revision does not identify the frozen execution context"
                .into(),
        });
    }
    if let Some(expected_profile_hash) = &input.expected_profile_hash
        && expected_profile_hash != &context.context.profile_hash
    {
        return api_error(Error::IntakeConflict {
            code: "PROFILE_HASH_MISMATCH",
            message: "the expected profile hash does not identify the frozen execution context"
                .into(),
        });
    }
    let expected = match factory_native::db::ExpectedStartBinding::new(
        &context.lead.request_hash,
        &context.plan.plan_hash,
        &context.spec_sha256,
        &context.lead.project_config_hash,
        &context.grant.content_hash,
        Some(&context.context.profile_revision_id),
        Some(&context.context.profile_hash),
    ) {
        Ok(binding) => binding,
        Err(error) => return api_error(error),
    };
    if let Err(response) = ensure_planning_ready(&app, &context.intake).await {
        return response;
    }
    let billable = context.mechanism == "MODEL";
    let production = !cfg!(any(test, feature = "test-support"));
    let subscription_admission_id = match input.subscription_admission_id.clone() {
        Some(admission_id) => Some(admission_id),
        None => match app.db.active_subscription_admission_for_request(&id).await {
            Ok(admission_id) => admission_id,
            Err(error) => return api_error(error),
        },
    };
    let monetary_envelope_id = if billable && (production || subscription_admission_id.is_some()) {
        // Subscription-only policy: MODEL approval requires an exact
        // Owner-confirmed admission created before assessment. The legacy
        // billable envelope path is not accepted in production. Office may
        // omit the id when exactly one active admission is bound to the
        // request; the start transaction still consumes and validates it.
        if subscription_admission_id.is_none() {
            return api_error(Error::IntakeConflict {
                code: "SUBSCRIPTION_ADMISSION_REQUIRED",
                message:
                    "MODEL execution requires an Owner-confirmed subscription admission created before assessment"
                        .into(),
            });
        }
        if input.authorized_micros.is_some() {
            return api_error(Error::IntakeConflict {
                code: "MONETARY_AUTHORIZATION_NOT_APPLICABLE",
                message: "subscription execution has no monetary envelope".into(),
            });
        }
        factory_native::db::NO_BILLABLE_ENVELOPE.to_owned()
    } else if billable {
        // Debug/test-support fixture path retained for deterministic E2E only.
        let envelope = match app
            .db
            .inference_envelope_for_request(&context.intake.id)
            .await
        {
            Ok(Some(envelope)) => envelope,
            Ok(None) => {
                return api_error(Error::IntakeConflict {
                    code: "INFERENCE_AUTHORIZATION_REQUIRED",
                    message:
                        "billable execution requires an operator-authorized monetary amount at request creation"
                            .into(),
                });
            }
            Err(error) => return api_error(error),
        };
        if let Some(authorized_micros) = input.authorized_micros
            && authorized_micros != envelope.authorized_micros.get()
        {
            return api_error(Error::IntakeConflict {
                code: "INFERENCE_AUTHORIZATION_CHANGED",
                message: "approval changed the operator inference authorization".into(),
            });
        }
        envelope.envelope_id
    } else {
        if input.authorized_micros.is_some() {
            return api_error(Error::IntakeConflict {
                code: "INFERENCE_AUTHORIZATION_NOT_APPLICABLE",
                message: "fixture execution has no billable inference envelope".into(),
            });
        }
        factory_native::db::NO_BILLABLE_ENVELOPE.to_owned()
    };
    let authorization = build_intake_authorization(
        &context,
        principal_label,
        &principal_id,
        &input.rationale,
        &monetary_envelope_id,
    );
    let idempotency_key = input
        .idempotency_key
        .clone()
        .unwrap_or_else(|| format!("intake-approve:{id}:{}", context.plan.plan_hash));
    match app
        .db
        .start_lead_campaign_with_admission(
            &context.lead.id,
            &idempotency_key,
            factory_native::db::StartAuthority::Operator(approval),
            Some(&expected),
            Some(&authorization),
            subscription_admission_id.as_deref(),
        )
        .await
    {
        Ok(result) => {
            let record = match app.db.intake_request(&id).await {
                Ok(record) => record,
                Err(error) => return api_error(error),
            };
            let value = match intake_request_value(&app, &record, true).await {
                Ok(value) => value,
                Err(error) => return api_error(error),
            };
            (
                if result.replayed {
                    StatusCode::OK
                } else {
                    StatusCode::CREATED
                },
                Json(value),
            )
                .into_response()
        }
        Err(error) => api_error(error),
    }
}

async fn message_intake_request(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    Json(input): Json<IntakeMessageRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let (message, created) = match app
        .db
        .append_intake_message(&id, &input.body, &input.idempotency_key)
        .await
    {
        Ok(result) => result,
        Err(error) => return api_error(error),
    };
    let _ = message;
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    match intake_request_value(&app, &record, true).await {
        Ok(value) => (
            if created {
                StatusCode::CREATED
            } else {
                StatusCode::OK
            },
            Json(value),
        )
            .into_response(),
        Err(error) => api_error(error),
    }
}

async fn cancel_intake_request(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    session: Option<Extension<factory_native::db::DeviceSessionRecord>>,
    Json(input): Json<CancelIntakeRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let (principal_id, device_label) =
        authenticated_operator(session.as_ref().map(|Extension(device)| device));
    let record = match app.db.intake_request(&id).await {
        Ok(record) => record,
        Err(error) => return api_error(error),
    };
    if let Err(error) = app
        .db
        .withdraw_lead_request(
            &record.lead_request_id,
            &principal_id,
            device_label.as_deref(),
            &input.reason,
        )
        .await
    {
        return api_error(error);
    }
    match intake_request_value(&app, &record, true).await {
        Ok(value) => Json(value).into_response(),
        Err(error) => api_error(error),
    }
}

async fn create_execution_policy(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    session: Option<Extension<factory_native::db::DeviceSessionRecord>>,
    Json(input): Json<ExecutionPolicyRequest>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let (principal_id, device_label) =
        authenticated_operator(session.as_ref().map(|Extension(device)| device));
    match app
        .db
        .create_execution_policy_grant(factory_native::db::NewExecutionPolicyGrant {
            project_id: &id,
            profile_id: &input.execution_profile_id,
            expected_revision: input.expected_revision,
            expected_revision_hash: &input.expected_revision_hash,
            project_config_hash: &input.project_config_hash,
            acknowledge: input.acknowledge,
            autonomous: input.autonomous,
            subscription_confirmed: input.subscription_confirmed,
            idempotency_key: &input.idempotency_key,
            principal_id: &principal_id,
            principal_label: device_label.as_deref(),
        })
        .await
    {
        Ok(result) => (
            if result.created {
                StatusCode::CREATED
            } else {
                StatusCode::OK
            },
            Json(json!({
                "grant": result.grant,
                "delegation": result.delegation,
                "usage": result.usage,
                "replayed": !result.created,
            })),
        )
            .into_response(),
        Err(error) => api_error(error),
    }
}

async fn authorize_campaign(
    State(app): State<Arc<App>>,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    Json(input): Json<AuthorizeCampaign>,
) -> Response {
    if !authorized(&headers, &app.operator_token) {
        return StatusCode::UNAUTHORIZED.into_response();
    }
    let campaign = match app.db.campaign(&id).await {
        Ok(campaign) => campaign,
        Err(error) => return api_error(error),
    };
    let action_spec = match app.db.action(&campaign.action_id).await {
        Ok(action) => action.spec,
        Err(error) => return api_error(error),
    };
    if action_spec.environment_spec_sha256.is_none() || !action_spec.environment_required {
        return (
            StatusCode::CONFLICT,
            Json(json!({
                "error": "the Campaign ActionSpec has no frozen environment plan/spec; Core refuses to authorize execution rather than selecting a language image.",
                "code": "ENVIRONMENT_PLAN_REQUIRED",
            })),
        )
            .into_response();
    }
    if let Err(error) = factory_native::db::validate_environment_requirement(&action_spec) {
        return api_error(error);
    }
    match app.db.intake_request_for_campaign(&id).await {
        Ok(record) => {
            if let Err(response) = ensure_planning_ready(&app, &record).await {
                return response;
            }
        }
        Err(Error::NotFound) => {}
        Err(error) => return api_error(error),
    }
    let authorization = match input.execution_mode.as_str() {
        "FIXTURE" => {
            if input.monetary_envelope_id.is_some() || input.authorized_micros.is_some() {
                return api_error(Error::Conflict(
                    "fixture authorization has no billable inference envelope",
                ));
            }
            input.into_new(factory_native::db::NO_BILLABLE_ENVELOPE.to_owned())
        }
        // A provider Campaign needs the one operator-request envelope and its
        // atomic Campaign binding. Direct-route authorization has no request
        // identity to own that envelope, so it fails closed instead of
        // authorizing unbindable spending.
        "TRUSTED_LOCAL_PROVIDER" => {
            return api_error(Error::Forbidden(
                "provider execution requires a request-scoped Lead/intake approval; submit a new request instead of a direct Campaign authorization"
                    .into(),
            ));
        }
        _ => {
            return api_error(Error::Forbidden(
                "only FIXTURE and TRUSTED_LOCAL_PROVIDER execution are enabled".into(),
            ));
        }
    };
    match app.db.authorize_campaign(&id, &authorization).await {
        Ok((record, created)) => (
            if created {
                StatusCode::CREATED
            } else {
                StatusCode::OK
            },
            Json(record),
        )
            .into_response(),
        Err(error) => api_error(error),
    }
}

