        fn git_repository() -> PathBuf {
            let repository = std::env::temp_dir()
                .join(format!("factory-core-intake-repo-{}", uuid::Uuid::new_v4()));
            std::fs::create_dir(&repository).unwrap();
            for arguments in [
                vec!["init", "-q"],
                vec!["config", "user.name", "Fixture"],
                vec!["config", "user.email", "fixture@example.invalid"],
            ] {
                assert!(
                    std::process::Command::new("git")
                        .arg("-C")
                        .arg(&repository)
                        .args(arguments)
                        .status()
                        .unwrap()
                        .success()
                );
            }
            std::fs::write(repository.join("seed.txt"), "seed\n").unwrap();
            std::fs::write(
                repository.join("devenv.nix"),
                "{ pkgs, ... }: { packages = [ ]; }\n",
            )
            .unwrap();
            std::fs::write(
                repository.join("devenv.lock"),
                "{\"nodes\":{\"nixpkgs\":{\"locked\":{\"owner\":\"NixOS\",\"repo\":\"nixpkgs\",\"rev\":\"1111111111111111111111111111111111111111\"}}}}\n",
            )
            .unwrap();
            for arguments in [vec!["add", "--all"], vec!["commit", "-qm", "seed"]] {
                assert!(
                    std::process::Command::new("git")
                        .arg("-C")
                        .arg(&repository)
                        .args(arguments)
                        .status()
                        .unwrap()
                        .success()
                );
            }
            repository
        }

        struct Fixture {
            path: PathBuf,
            repository: PathBuf,
            app: Arc<App>,
            project_id: String,
            config: factory_native::lead::ProjectConfig,
            profile: factory_native::db::ExecutionProfileRecord,
            router: Router,
        }

        async fn setup() -> Fixture {
            setup_with(
                None,
                "https://provider.example/v1",
                "https://provider.example/v1",
                profile_content(),
            )
            .await
        }

        async fn setup_with(
            master_key: Option<&factory_native::provider_secrets::ProviderSecretKey>,
            opencode_go_base_url: &str,
            opencode_base_url: &str,
            profile_content: factory_native::execution_profile::ExecutionProfileContent,
        ) -> Fixture {
            setup_with_projects_root(
                master_key,
                opencode_go_base_url,
                opencode_base_url,
                profile_content,
                None,
            )
            .await
        }

        async fn setup_with_projects_root(
            master_key: Option<&factory_native::provider_secrets::ProviderSecretKey>,
            opencode_go_base_url: &str,
            opencode_base_url: &str,
            profile_content: factory_native::execution_profile::ExecutionProfileContent,
            projects_root: Option<PathBuf>,
        ) -> Fixture {
            let path = std::env::temp_dir().join(format!(
                "factory-core-intake-{}.sqlite",
                uuid::Uuid::new_v4()
            ));
            let repository = git_repository();
            let app = test_app_with_master_key_and_options(
                &path,
                master_key.cloned(),
                false,
                projects_root,
            )
            .await;
            let project = app
                .db
                .register_project(&repository, "intake-project-key")
                .await
                .unwrap();
            let config = app
                .db
                .update_project_config(
                    &project.id,
                    &NewProjectConfig {
                        expected_revision: 1,
                        allowed_paths: vec!["src".into()],
                        capabilities: vec![Capability::RepositoryEdit],
                        quality_profile: QualityProfile::Generic,
                        active: true,
                    },
                )
                .await
                .unwrap();
            for (provider, kind, model, base_url, is_default) in [
                (
                    "opencode-go",
                    "opencode",
                    "deepseek-v4.1-flash",
                    opencode_go_base_url,
                    true,
                ),
                (
                    "codex",
                    "codex",
                    "gpt-6-luna",
                    "https://provider.example/v1",
                    false,
                ),
                (
                    "opencode",
                    "opencode",
                    "deepseek-v4.1-flash",
                    opencode_base_url,
                    false,
                ),
            ] {
                let encrypted = match master_key {
                    Some(key) => {
                        let value = format!("{provider}-credential-1234567890");
                        let encrypted = key.encrypt(value.as_bytes()).unwrap();
                        factory_native::provider_secrets::EncryptedCredential {
                            ciphertext: encrypted.ciphertext,
                            nonce: encrypted.nonce,
                            fingerprint: encrypted.fingerprint,
                        }
                    }
                    None => factory_native::provider_secrets::EncryptedCredential {
                        ciphertext: "ciphertext".into(),
                        nonce: "nonce".into(),
                        fingerprint: "fingerprint".into(),
                    },
                };
                app.db
                    .save_provider_settings(
                        &ProviderSettingsWrite {
                            provider: provider.into(),
                            kind: kind.into(),
                            model: model.into(),
                            base_url: base_url.into(),
                            auth_mode: "api_key".into(),
                            credential_ciphertext: encrypted.ciphertext,
                            credential_nonce: encrypted.nonce,
                            credential_fingerprint: encrypted.fingerprint,
                            enabled: true,
                            is_default,
                            max_turns: 4,
                            max_input_tokens: 100_000,
                            max_output_tokens: 12_000,
                            max_cost_micros: 500_000,
                            input_micros_per_million: 1_000,
                            output_micros_per_million: 2_000,
                        },
                        "test-operator",
                    )
                    .await
                    .unwrap();
            }
            let profile = app
                .db
                .create_execution_profile(&profile_content, "owner")
                .await
                .unwrap();
            let router = build_router(Arc::clone(&app));
            Fixture {
                path,
                repository,
                app,
                project_id: project.id,
                config,
                profile,
                router,
            }
        }

        async fn send(
            router: &Router,
            method: &str,
            uri: &str,
            body: Option<Value>,
        ) -> (StatusCode, Value) {
            send_as(router, method, uri, "operator-token", body).await
        }

        async fn send_as(
            router: &Router,
            method: &str,
            uri: &str,
            token: &str,
            body: Option<Value>,
        ) -> (StatusCode, Value) {
            let mut builder = axum::http::Request::builder()
                .method(method)
                .uri(uri)
                .header("authorization", format!("Bearer {token}"));
            let body = if let Some(body) = body {
                builder = builder.header("content-type", "application/json");
                axum::body::Body::from(body.to_string())
            } else {
                axum::body::Body::empty()
            };
            let response = router
                .clone()
                .oneshot(builder.body(body).unwrap())
                .await
                .unwrap();
            let status = response.status();
            let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
                .await
                .unwrap();
            let value = if bytes.is_empty() {
                Value::Null
            } else {
                serde_json::from_slice(&bytes).unwrap()
            };
            (status, value)
        }

